  tb(["Agency House", "Detail"], ["What", "British trading + financial firm: cross of private bank, investment firm, business management company"], ["Did", "Raised capital, credit, financed trade; agents running tea plantations, jute mills, coal mines, shipping"], ["Today's words", "<b>NBFC + private equity + holding company</b>"], ["Managing agency system", "One firm managing many businesses for fee or profit share; dominant in colonial economy"], ["Examples", "Andrew Yule and Company, Jardine Henderson, Bird and Company"], ["End", "Abolished <b>1970</b>: concentrated economic power, vehicle of drain + monopoly"]),
